    return false;
  }
  // 13. The person who plays football drinks orange juice.
  for (const h of HOUSES) {
    if (hobbies[h] === 'Football' && beverages[h] !== 'Orange juice') return false;
    if (beverages[h] === 'Orange juice' && hobbies[h] !== 'Football') return false;
  }
  // 14. The Japanese person plays chess.
  for (const h of HOUSES) {
    if (nations[h] === 'Japanese' && hobbies[h] !== 'Chess') return false;
    if (hobbies[h] === 'Chess' && nations[h] !== 'Japanese') return false;
